/* From Uiverse.io by vinodjangid07  - Tags: animation, purple, loading, loader, search */
.__UIV_SCOPE__ .loader {
  display: flex;
  align-items: center;
  justify-content: center;
}
.__UIV_SCOPE__ .loaderMiniContainer {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  width: 130px;
  height: fit-content;
}
.__UIV_SCOPE__ .barContainer {
  width: 100%;
  height: fit-content;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 10px;
  background-position: left;
}
.__UIV_SCOPE__ .bar {
  width: 100%;
  height: 8px;
  background: linear-gradient(
    to right,
    rgb(161, 94, 255),
    rgb(217, 190, 255),
    rgb(161, 94, 255)
  );
  background-size: 200% 100%;
  border-radius: 10px;
  animation: bar ease-in-out 3s infinite alternate-reverse;
}
@keyframes bar {
  0% {
    background-position: left;
  }
  100% {
    background-position: right;
  }
}
.__UIV_SCOPE__ .bar2 {
  width: 50%;
}
.__UIV_SCOPE__ .svgIcon {
  position: absolute;
  left: -25px;
  margin-top: 18px;
  z-index: 2;
  width: 70%;
  animation: search ease-in-out 3s infinite alternate-reverse;
}
@keyframes search {
  0% {
    transform: translateX(0%) rotate(70deg);
  }

  100% {
    transform: translateX(100px) rotate(10deg);
  }
}
.__UIV_SCOPE__ .svgIcon circle,
.__UIV_SCOPE__ line {
  stroke: rgb(162, 55, 255);
}
.__UIV_SCOPE__ .svgIcon circle {
  fill: rgba(98, 65, 142, 0.238);
}
